mapper.select:
SELECT COUNT(1)
FROM biz_order
WHERE seat_id = #{seatId}
  AND order_status NOT IN (3, 4, 5)
  AND booking_end > #{start, jdbcType=TIMESTAMP}
  AND booking_start < #{end, jdbcType=TIMESTAMP}

mapper.update:
UPDATE biz_order
SET order_status = 1, pay_time = #{payTime, jdbcType=TIMESTAMP}, update_time = NOW()
WHERE id = #{id}

UPDATE biz_order
SET order_status = 4, cancel_reason = #{reason}, update_time = NOW()
WHERE id = #{id}

UPDATE biz_order
SET order_status = 5, update_time = NOW()
WHERE id = #{id}

UPDATE biz_order
SET order_status = 2, actual_start = #{actualStart, jdbcType=TIMESTAMP}, update_time = NOW()
WHERE id = #{id}

UPDATE biz_order
SET order_status = 3, actual_end = #{actualEnd, jdbcType=TIMESTAMP}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT 
FROM biz_order
WHERE order_status = 0
  AND expire_at < #{now, jdbcType=TIMESTAMP}
ORDER BY expire_at ASC
LIMIT #{limit}
